FUNCTION_BLOCK FB_EstrellaTriangulo
VAR
    // Entradas
    btnMarcha : BOOL;
    btnParo : BOOL;

    // Salidas
    kM : BOOL := FALSE;
    kY : BOOL := FALSE;
    kD : BOOL := FALSE;

    // Variables internas
    estado : INT := 0;
    timerEstrella : TON; // Temporizador para el modo estrella
    timerMuerto : TON;   // Temporizador para el tiempo muerto
END_VAR

// Inicialización de los temporizadores
timerEstrella(IN := FALSE, PT := T#8S);
timerMuerto(IN := FALSE, PT := T#100MS);

// Lógica de control
IF btnParo THEN
    // Si se presiona el botón de paro, desactivar todos los contactores
    kM := FALSE;
    kY := FALSE;
    kD := FALSE;
    estado := 0;
ELSIF btnMarcha THEN
    CASE estado OF
        0: // Estado inicial
            kM := TRUE; // Activar contactor principal
            kY := TRUE; // Activar contactor estrella
            timerEstrella(IN := TRUE); // Iniciar temporizador estrella
            estado := 1;

        1: // Esperando que termine el temporizador estrella
            IF timerEstrella.Q THEN
                kY := FALSE; // Desactivar contactor estrella
                timerEstrella(IN := FALSE); // Reiniciar temporizador estrella
                timerMuerto(IN := TRUE); // Iniciar temporizador muerto
                estado := 2;
            END_IF

        2: // Esperando que termine el tiempo muerto
            IF timerMuerto.Q THEN
                kD := TRUE; // Activar contactor triángulo
                timerMuerto(IN := FALSE); // Reiniciar temporizador muerto
                estado := 3;
            END_IF

        3: // Estado final, contactor triángulo activado
            // Mantener el estado hasta que se presione btnParo
            // o se desactive btnMarcha
            IF NOT btnMarcha THEN
                kM := FALSE;
                kD := FALSE;
                estado := 0;
            END_IF
    END_CASE
ELSE
    // Si btnMarcha no está activo, asegurarse de que todo esté apagado
    kM := FALSE;
    kY := FALSE;
    kD := FALSE;
    estado := 0;
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_EstrellaTriangulo
VAR_INPUT
    btnMarcha : BOOL; (* Botón de marcha *)
    btnParo : BOOL; (* Botón de paro *)
END_VAR
VAR_OUTPUT
    kM : BOOL; (* Contactor principal *)
    kY : BOOL; (* Contactor de estrella *)
    kD : BOOL; (* Contactor de triángulo *)
END_VAR
VAR
    tEstrella : TP; (* Temporizador para el contacto de estrella *)
    tMuerto : TP; (* Temporizador para el tiempo muerto *)
    estado : INT; (* Variable de estado para el arranque estrella-triángulo *)
END_VAR

(* Estado 0: Esperando inicio *)
(* Estado 1: Contacto de estrella activo *)
(* Estado 2: Tiempo muerto *)
(* Estado 3: Contacto de triángulo activo *)

(* Botón de paro desactiva todos los contactores *)
IF btnParo THEN
    kM := FALSE;
    kY := FALSE;
    kD := FALSE;
    estado := 0;
ELSIF btnMarcha THEN
    CASE estado OF
        0:
            (* Inicia el arranque estrella-triángulo *)
            kM := TRUE;
            kY := TRUE;
            kD := FALSE;
            tEstrella(IN := TRUE, PT := T#8S);
            estado := 1;
        1:
            (* Espera el fin del temporizador de estrella *)
            IF tEstrella.Q THEN
                kY := FALSE;
                tMuerto(IN := TRUE, PT := T#100MS);
                estado := 2;
            END_IF;
        2:
            (* Espera el fin del tiempo muerto *)
            IF tMuerto.Q THEN
                kD := TRUE;
                estado := 3;
            END_IF;
        3:
            (* Mantén el contacto de triángulo activo *)
            kY := FALSE;
    END_CASE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_EstrellaTriangulo
VAR_INPUT
    btnMarcha : BOOL; // Botón de arranque
    btnParo   : BOOL; // Botón de parada (TRUE = detener)
END_VAR

VAR_OUTPUT
    kM : BOOL; // Contactor principal
    kY : BOOL; // Contactor de estrella
    kD : BOOL; // Contactor de triángulo
END_VAR

VAR
    bRun        : BOOL; // Memoria del estado de marcha
    tonStar     : TON;  // Temporizador para la fase de estrella
    tonDeadTime : TON;  // Temporizador para el tiempo muerto
END_VAR

// 1. Lógica de retención (Marcha / Paro)
// El paro tiene prioridad sobre la marcha
IF btnParo THEN
    bRun := FALSE;
ELSIF btnMarcha THEN
    bRun := TRUE;
END_IF;

// 2. Temporizador de la fase de estrella (8 segundos)
tonStar(IN := bRun, PT := T#8S);

// 3. Control del contactor de Estrella (kY)
// Activo si hay marcha, no ha terminado el tiempo de estrella y kD está apagado (enclavamiento)
kY := bRun AND NOT tonStar.Q AND NOT kD;

// 4. Temporizador de tiempo muerto (100 milisegundos)
// Comienza a contar solo cuando termina la fase de estrella y kY se ha desactivado
tonDeadTime(IN := tonStar.Q AND NOT kY, PT := T#100MS);

// 5. Control del contactor de Triángulo (kD)
// Activo si hay marcha, terminó el tiempo muerto y kY está apagado (enclavamiento)
kD := bRun AND tonDeadTime.Q AND NOT kY;

// 6. Control del contactor Principal (kM)
// Activo siempre que el sistema esté en marcha
kM := bRun;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_EstrellaTriangulo
VAR
    // Entradas
    btnMarcha : BOOL;
    btnParo : BOOL;

    // Salidas
    kM : BOOL := FALSE;
    kY : BOOL := FALSE;
    kD : BOOL := FALSE;

    // Variables internas
    estado : INT := 0;
    timerEstrella : TON; // Temporizador para el modo estrella
    timerMuerto : TON;   // Temporizador para el tiempo muerto
END_VAR

// Configuración de los temporizadores
timerEstrella(IN := FALSE, PT := T#8S);
timerMuerto(IN := FALSE, PT := T#100MS);

// Lógica de control
IF btnParo THEN
    // Si se presiona el botón de paro, desactivar todos los contactores
    kM := FALSE;
    kY := FALSE;
    kD := FALSE;
    estado := 0;
ELSIF btnMarcha THEN
    CASE estado OF
        0: // Estado inicial
            kM := TRUE;
            kY := TRUE;
            timerEstrella(IN := TRUE);
            estado := 1;

        1: // Esperando el tiempo de estrella
            IF timerEstrella.Q THEN
                kY := FALSE;
                timerEstrella(IN := FALSE);
                timerMuerto(IN := TRUE);
                estado := 2;
            END_IF

        2: // Tiempo muerto entre estrella y triángulo
            IF timerMuerto.Q THEN
                kD := TRUE;
                timerMuerto(IN := FALSE);
                estado := 3;
            END_IF

        3: // Modo triángulo
            // Mantenerse en este estado hasta que se presione el botón de paro
            // No se requiere acción adicional
    END_CASE
ELSE
    // Si no se presiona ningún botón, asegurar que los contactores estén desactivados
    kM := FALSE;
    kY := FALSE;
    kD := FALSE;
    estado := 0;
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_EstrellaTriangulo
VAR_INPUT
    btnMarcha : BOOL; (* Botón de marcha *)
    btnParo : BOOL; (* Botón de paro *)
END_VAR
VAR_OUTPUT
    kM : BOOL; (* Contactor principal *)
    kY : BOOL; (* Contactor de estrella *)
    kD : BOOL; (* Contactor de triángulo *)
END_VAR
VAR
    tEstrella : TP; (* Temporizador para el contacto de estrella *)
    tMuerto : TP; (* Temporizador para el tiempo muerto *)
    estado : INT; (* Estado actual del arranque estrella-triángulo *)
END_VAR

(* Estados del arranque estrella-triángulo *)
CONST
    ESTADO_INICIAL := 0;
    ESTADO_ESTRELLA := 1;
    ESTADO_MUERTO := 2;
    ESTADO_TRIANGULO := 3;
END_CONST

(* Paro inmediato *)
IF btnParo THEN
    kM := FALSE;
    kY := FALSE;
    kD := FALSE;
    estado := ESTADO_INICIAL;
ELSIF btnMarcha THEN
    CASE estado OF
        ESTADO_INICIAL:
            kM := TRUE;
            kY := TRUE;
            kD := FALSE;
            tEstrella(IN := TRUE, PT := T#8S);
            estado := ESTADO_ESTRELLA;
        ESTADO_ESTRELLA:
            IF tEstrella.Q THEN
                kY := FALSE;
                tMuerto(IN := TRUE, PT := T#100MS);
                estado := ESTADO_MUERTO;
            END_IF;
        ESTADO_MUERTO:
            IF tMuerto.Q THEN
                kD := TRUE;
                estado := ESTADO_TRIANGULO;
            END_IF;
        ESTADO_TRIANGULO:
            (* Mantener kD activo mientras kY esté inactivo *)
            kD := TRUE;
    END_CASE;
END_IF;

(* Asegurar que kY y kD no estén activos simultáneamente *)
IF kY AND kD THEN
    kY := FALSE;
END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_EstrellaTriangulo
VAR_INPUT
    btnMarcha : BOOL; // Botón de marcha
    btnParo : BOOL; // Botón de paro
END_VAR

VAR_OUTPUT
    kM : BOOL; // Contactor principal
    kY : BOOL; // Contactor de estrella
    kD : BOOL; // Contactor de triángulo
END_VAR

VAR
    timerStar : TON; // Temporizador para el contacto de estrella
    timerDelta : TON; // Temporizador para el contacto de triángulo
    state : INT := 0; // Estado actual del programa
    deadTime : TON; // Temporizador para el tiempo muerto
END_VAR

// Inicialización de temporizadores
timerStar(IN := FALSE, PT := T#8S);
timerDelta(IN := FALSE, PT := T#100MS);
deadTime(IN := FALSE, PT := T#100MS);

// Lógica del programa
CASE state OF
    0: // Estado inicial
        IF btnMarcha THEN
            kM := TRUE;
            kY := TRUE;
            timerStar(IN := TRUE);
            state := 1;
        END_IF
        IF btnParo THEN
            kM := FALSE;
            kY := FALSE;
            kD := FALSE;
            state := 0;
        END_IF

    1: // Esperando para desactivar kY
        IF timerStar.Q THEN
            kY := FALSE;
            timerStar(IN := FALSE);
            deadTime(IN := TRUE);
            state := 2;
        END_IF
        IF btnParo THEN
            kM := FALSE;
            kY := FALSE;
            kD := FALSE;
            state := 0;
        END_IF

    2: // Tiempo muerto
        IF deadTime.Q THEN
            kD := TRUE;
            deadTime(IN := FALSE);
            state := 3;
        END_IF
        IF btnParo THEN
            kM := FALSE;
            kY := FALSE;
            kD := FALSE;
            state := 0;
        END_IF

    3: // Estado final
        IF btnParo THEN
            kM := FALSE;
            kY := FALSE;
            kD := FALSE;
            state := 0;
        END_IF
END_CASE

FUNCTION_BLOCK FB_EstrellaTriangulo
VAR_INPUT
    btnMarcha : BOOL; (* Boton de marcha *)
    btnParo : BOOL; (* Boton de paro *)
END_VAR
VAR_OUTPUT
    kM : BOOL; (* Contactor principal *)
    kY : BOOL; (* Contactor de estrella *)
    kD : BOOL; (* Contactor de triangulo *)
END_VAR
VAR
    tEstrella : TP; (* Temporizador para el contacto de estrella *)
    tMuerto : TP; (* Temporizador para el tiempo muerto *)
    estado : INT := 0; (* Estado actual del arranque *)
END_VAR

(* Estado 0: Esperando el botón de marcha *)
IF btnMarcha AND estado = 0 THEN
    estado := 1;
    kM := TRUE;
    kY := TRUE;
    kD := FALSE;
    tEstrella(IN := TRUE, PT := T#8S);
ELSIF btnParo THEN
    estado := 0;
    kM := FALSE;
    kY := FALSE;
    kD := FALSE;
END_IF

(* Estado 1: Esperando el temporizador de estrella *)
IF estado = 1 AND tEstrella.Q THEN
    estado := 2;
    kY := FALSE;
    tMuerto(IN := TRUE, PT := T#100MS);
END_IF

(* Estado 2: Esperando el tiempo muerto *)
IF estado = 2 AND tMuerto.Q THEN
    estado := 3;
    kD := TRUE;
END_IF

(* Mantener kY y kD inactivos simultáneamente *)
IF kY AND kD THEN
    kY := FALSE;
    kD := FALSE;
END_IF

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_EstrellaTriangulo
VAR_INPUT
    btnMarcha : BOOL; // Botón de marcha
    btnParo : BOOL;   // Botón de paro
END_VAR

VAR_OUTPUT
    kM : BOOL := FALSE; // Contactor principal
    kY : BOOL := FALSE; // Contactor estrella
    kD : BOOL := FALSE; // Contactor triángulo
END_VAR

VAR
    timerEstrella : TON; // Temporizador para el modo estrella
    timerMuerto : TON;   // Temporizador para el tiempo muerto
    estado : INT := 0;   // Estado del proceso
END_VAR

// Implementación del arranque estrella-triángulo
IF btnParo THEN
    // Si se presiona el botón de paro, desactivar todos los contactores y resetear el estado
    kM := FALSE;
    kY := FALSE;
    kD := FALSE;
    estado := 0;
ELSE
    CASE estado OF
        0: // Estado inicial
            IF btnMarcha THEN
                // Al presionar el botón de marcha, activar el contactor principal y el de estrella
                kM := TRUE;
                kY := TRUE;
                timerEstrella(IN := TRUE, PT := T#8S);
                estado := 1;
            END_IF

        1: // Estado de temporización en estrella
            IF timerEstrella.Q THEN
                // Después de 8 segundos, desactivar el contactor de estrella y activar el temporizador muerto
                kY := FALSE;
                timerEstrella(IN := FALSE);
                timerMuerto(IN := TRUE, PT := T#100MS);
                estado := 2;
            END_IF

        2: // Estado de tiempo muerto
            IF timerMuerto.Q THEN
                // Después de 100 ms, activar el contactor de triángulo
                timerMuerto(IN := FALSE);
                kD := TRUE;
                estado := 3;
            END_IF

        3: // Estado de funcionamiento en triángulo
            // Mantener el estado hasta que se presione el botón de paro
            // No se requiere acción adicional aquí
    END_CASE
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_EstrellaTriangulo
VAR_INPUT
    btnMarcha : BOOL; // Botón de marcha
    btnParo : BOOL;   // Botón de paro
END_VAR

VAR_OUTPUT
    kM : BOOL; // Contactor principal
    kY : BOOL; // Contactor de estrella
    kD : BOOL; // Contactor de triángulo
END_VAR

VAR
    timerEstrella : TON; // Temporizador para el contacto de estrella
    timerMuerto : TON;   // Temporizador para el tiempo muerto
    estado : INT;       // Estado actual del arranque estrella-triángulo
END_VAR

// Estados del arranque estrella-triángulo
CONST
    ESTADO_INICIAL := 0;
    ESTADO_MARCHA := 1;
    ESTADO_TIEMPO_MUERTO := 2;
    ESTADO_TRIANGULO := 3;
END_CONST

// Inicialización
IF NOT btnParo THEN
    CASE estado OF
        ESTADO_INICIAL:
            kM := FALSE;
            kY := FALSE;
            kD := FALSE;
            IF btnMarcha THEN
                estado := ESTADO_MARCHA;
                kM := TRUE;
                kY := TRUE;
                timerEstrella(IN := TRUE, PT := T#8S);
            END_IF;

        ESTADO_MARCHA:
            IF timerEstrella.Q THEN
                estado := ESTADO_TIEMPO_MUERTO;
                kY := FALSE;
                timerMuerto(IN := TRUE, PT := T#100MS);
            END_IF;

        ESTADO_TIEMPO_MUERTO:
            IF timerMuerto.Q THEN
                estado := ESTADO_TRIANGULO;
                kD := TRUE;
            END_IF;

        ESTADO_TRIANGULO:
            // Mantener kD activo mientras no se presione btnParo
            kD := TRUE;
    END_CASE;
ELSE
    // Paro forzado
    estado := ESTADO_INICIAL;
    kM := FALSE;
    kY := FALSE;
    kD := FALSE;
    timerEstrella(IN := FALSE);
    timerMuerto(IN := FALSE);
END_IF;

FUNCTION_BLOCK FB_EstrellaTriangulo
VAR_INPUT
    btnMarcha : BOOL; // Botón de arranque
    btnParo   : BOOL; // Botón de parada (prioridad a la parada)
END_VAR

VAR_OUTPUT
    kM : BOOL; // Contactor principal
    kY : BOOL; // Contactor de estrella
    kD : BOOL; // Contactor de triángulo
END_VAR

VAR
    tonEstrella   : TON; // Temporizador para la fase de estrella (8s)
    tonTransicion : TON; // Temporizador para el tiempo muerto (100ms)
END_VAR

// 1. Lógica del contactor principal (kM)
// Enclavamiento con btnMarcha, se rompe al pulsar btnParo
kM := (btnMarcha OR kM) AND NOT btnParo;

// 2. Temporizadores
// El temporizador de estrella inicia al arrancar el motor (kM = TRUE)
tonEstrella(IN := kM, PT := T#8S);

// El temporizador de transición inicia cuando termina la fase de estrella
tonTransicion(IN := tonEstrella.Q, PT := T#100MS);

// 3. Lógica de los contactores de fase (con enclavamiento mutuo de seguridad)
// kY se activa con kM, se apaga al terminar tonEstrella, y nunca si kD está activo
kY := kM AND NOT tonEstrella.Q AND NOT kD;

// kD se activa al terminar el tiempo muerto, y nunca si kY está activo
kD := kM AND tonTransicion.Q AND NOT kY;

END_FUNCTION_BLOCK
